import React from 'react';
import {EscenaProps, Pieza, Etiqueta, Flecha, Ojos, Aro, aparecer, rebote, flotar, mover, momento} from '../lib3d';

export const Escena3: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [terracota, crema, azul, mostaza, sueloTono] = paleta.acentos;
  const piel = '#E8C4A2';
  const pielSombra = '#D6AE8B';
  const blancoBola = '#EEEAE2';
  const metal = '#9A9A9E';
  const metalOscuro = '#6E6E73';
  const panel = '#2F3A4C';
  const panelLinea = '#46536A';
  const sudor = '#B8D0E4';

  // Golpes con la voz
  const tProblema = momento(palabras, fps, 'problema', 8);
  const tPierde = momento(palabras, fps, 'pierde', 31);
  const tAgarre = momento(palabras, fps, 'agarre', 38);
  const tDedos = momento(palabras, fps, 'dedos', 61);
  const tMenos = momento(palabras, fps, 'menos', 83);
  const tApoyo = momento(palabras, fps, 'apoyarse', Math.round(duracion * 0.93));

  // Pelota: tiembla en la mano, micro-resbalón en "problema", se escapa como jabón en "agarre"
  const R = 0.42;
  const micro = mover(frame, [tProblema, tProblema + 6], [0, 1]) * (1 - mover(frame, [tProblema + 6, tProblema + 14], [0, 1]));
  const temblor = Math.sin(frame / 2.2) * 0.012 * aparecer(frame, tPierde, 6);
  const p = mover(frame, [tAgarre, tAgarre + 16], [0, 1]);
  const caida = p * p;
  const bote = frame > tAgarre + 16 ? Math.abs(Math.sin((frame - tAgarre - 16) / 4)) * 0.12 * Math.exp(-(frame - tAgarre - 16) / 10) : 0;
  const bolaX = 0.06 * micro + temblor + 0.48 * Math.sin(p * Math.PI * 0.5);
  const bolaY = 1.05 - 0.05 * micro - (1.05 - R) * caida + bote;
  const chorro = Math.sin(Math.min(1, p * 2) * Math.PI) * 0.18; // se aplasta al salir disparada
  const aplasta: [number, number, number] = [1 + chorro, 1 - chorro * 0.7, 1 + chorro * 0.3];
  const aterriza = rebote(frame, fps, tAgarre + 16);

  // Mano: los dedos se cierran sobre el aire cuando la pelota se escapa
  const cierre = mover(frame, [tAgarre, tAgarre + 10], [-0.62, -1.45]);
  const sacudida = mover(frame, [tAgarre, tAgarre + 8], [0, 0.08]);
  const manoY = 1.5 + sacudida + flotar(frame, 0.012, 40);
  const destacaDedos = aparecer(frame, tDedos, 8);
  const colorDedo = destacaDedos > 0.5 && frame < tMenos + 12 ? pielSombra : piel;

  const dedos = [-0.18, -0.06, 0.06, 0.18];
  const gotas = [0, 1, 2, 3, 4];

  return (
    <group>
      {/* FONDO: panel del laboratorio con cuadrícula tenue */}
      <group position={[0, 0, -1.5]}>
        <Pieza forma="caja" medidas={[2.6, 1.85, 0.06]} color={panel} posicion={[0, 0.95, 0]} />
        {[-1, -0.5, 0, 0.5, 1].map((x) => (
          <Pieza key={`v${x}`} forma="caja" medidas={[0.012, 1.8, 0.01]} color={panelLinea} posicion={[x, 0.95, 0.04]} contorno={false} />
        ))}
        {[0.35, 0.8, 1.25, 1.7].map((y) => (
          <Pieza key={`h${y}`} forma="caja" medidas={[2.55, 0.012, 0.01]} color={panelLinea} posicion={[0, y, 0.04]} contorno={false} />
        ))}
      </group>

      {/* FONDO: pinzas metálicas grandes en su soporte */}
      <group position={[-0.95, 0, -0.9]} rotation={[0, 0.4, 0]}>
        <Pieza forma="cilindro" medidas={[0.18, 0.2, 0.05]} color={metalOscuro} posicion={[0, 0.025, 0]} metal={0.6} />
        <Pieza forma="cilindro" medidas={[0.025, 0.025, 0.9]} color={metal} posicion={[0, 0.5, 0]} metal={0.6} />
        <Pieza forma="caja" medidas={[0.08, 0.08, 0.08]} color={metalOscuro} posicion={[0, 0.95, 0]} />
        <Pieza forma="caja" medidas={[0.03, 0.4, 0.04]} color={metal} posicion={[0.07, 1.12, 0]} rotacion={[0, 0, -0.25]} />
        <Pieza forma="caja" medidas={[0.03, 0.4, 0.04]} color={metal} posicion={[-0.07, 1.12, 0]} rotacion={[0, 0, 0.25]} />
      </group>

      {/* Tapete bajo la acción */}
      <Pieza forma="cilindro" medidas={[0.85, 0.85, 0.03]} color={sueloTono} posicion={[0.15, 0.015, 0]} />

      {/* MEDIO: la pelota lisa, sin costuras */}
      <group position={[bolaX, bolaY, 0]}>
        <group scale={aplasta} rotation={[0, 0, -p * 2.5]}>
          <Pieza forma="esfera" medidas={[R]} color={blancoBola} />
          {/* brillo mojado, como jabón */}
          <Pieza forma="esfera" medidas={[0.09]} color="#FFFFFF" posicion={[-0.17, 0.2, 0.3]} escala={[1, 0.6, 0.4]} contorno={false} opacidad={0.85} />
        </group>
        <Ojos
          posicion={[0, 0.02, R * 0.93]}
          tam={0.085}
          separacion={0.2}
          mirar={[
            mover(frame, [tProblema, tProblema + 6, tAgarre, tAgarre + 8], [0, -0.4, -0.4, 0.6]),
            mover(frame, [tProblema, tProblema + 6, tAgarre, tAgarre + 8], [0, 0.9, 0.9, -0.6]),
          ]}
          frame={frame}
        />
      </group>
      <Aro posicion={[0.48, 0, 0]} radio={0.5} color={azul} progreso={aparecer(frame, tApoyo, 8) * aterriza} />

      {/* MEDIO: mano del lanzador, palma hacia abajo */}
      <group position={[0, manoY, 0]} rotation={[0.1 + sacudida, 0, flotar(frame, 0.03, 50)]}>
        {/* manga y puño azul */}
        <Pieza forma="cilindro" medidas={[0.2, 0.2, 0.5]} color={azul} posicion={[0, 0.05, -0.55]} rotacion={[Math.PI / 2 - 0.25, 0, 0]} />
        <Pieza forma="toro" medidas={[0.2, 0.04]} color={crema} posicion={[0, 0.0, -0.32]} rotacion={[-0.25, 0, 0]} />
        <Pieza forma="cilindro" medidas={[0.16, 0.17, 0.14]} color={piel} posicion={[0, 0, -0.22]} rotacion={[Math.PI / 2, 0, 0]} />
        {/* palma */}
        <Pieza forma="caja" medidas={[0.5, 0.14, 0.44]} color={piel} posicion={[0, 0, 0]} />
        {/* nudillos */}
        {dedos.map((x) => (
          <Pieza key={`n${x}`} forma="esfera" medidas={[0.065]} color={piel} posicion={[x, 0.0, 0.22]} />
        ))}
        {/* dedos que se cierran */}
        {dedos.map((x, i) => (
          <group key={`d${x}`} position={[x, -0.02, 0.24]} rotation={[cierre - (i % 2) * 0.05, 0, 0]}>
            <Pieza forma="capsula" medidas={[0.055, i === 0 || i === 3 ? 0.2 : 0.25]} color={colorDedo} posicion={[0, -0.17, 0]} />
            <Pieza forma="esfera" medidas={[0.035]} color={crema} posicion={[0, -0.3, 0.035]} escala={[1, 0.6, 0.4]} contorno={false} />
          </group>
        ))}
        {/* pulgar */}
        <group position={[-0.27, -0.03, 0.02]} rotation={[0, 0, mover(frame, [tAgarre, tAgarre + 10], [-0.5, -1.1])]}>
          <Pieza forma="capsula" medidas={[0.06, 0.22]} color={colorDedo} posicion={[0, -0.16, 0]} />
        </group>
      </group>

      {/* Gotitas de sudor que caen de los dedos */}
      {gotas.map((i) => {
        const inicio = tPierde + i * 5;
        if (frame < inicio) return null;
        const ciclo = ((frame - inicio) % 22) / 22;
        const x = -0.2 + i * 0.1 + (i % 2) * 0.03;
        return (
          <group key={`g${i}`} position={[x, 1.25 - ciclo * 0.7, 0.48 + (i % 3) * 0.04]} scale={Math.sin(ciclo * Math.PI) * 1.1}>
            <Pieza forma="esfera" medidas={[0.035]} color={sudor} />
            <Pieza forma="cono" medidas={[0.03, 0.06]} color={sudor} posicion={[0, 0.045, 0]} />
          </group>
        );
      })}
      {/* gotas que salen disparadas al resbalar */}
      {[0, 1, 2].map((i) => {
        const s = mover(frame, [tAgarre, tAgarre + 14], [0, 1]);
        if (s <= 0 || s >= 1) return null;
        return (
          <Pieza key={`s${i}`} forma="esfera" medidas={[0.03]} color={sudor}
            posicion={[0.2 + s * (0.3 + i * 0.12), 1.15 + Math.sin(s * Math.PI) * (0.15 + i * 0.05) - s * 0.2, 0.4]} />
        );
      })}

      {/* Flecha de resbalón */}
      <Flecha desde={[0.5, 1.2, 0.3]} hasta={[0.88, 0.7, 0.3]} color={terracota} grosor={0.025}
        progreso={mover(frame, [tAgarre, tAgarre + 10], [0, 1])} />

      {/* Etiquetas (como mucho 2) */}
      <Etiqueta texto="sin agarre" punto={[-0.2, 1.3, 0.4]} desplazamiento={[-0.5, 0.3, 0.1]} escala={aparecer(frame, tAgarre, 8)} color="#FFFFFF" />
      <Etiqueta texto="dedos" punto={[0.18, 1.35, 0.45]} desplazamiento={[0.55, 0.25, 0]} escala={aparecer(frame, tDedos, 8)} color={crema} />

      {/* DELANTE: bolsa de resina y placa del lanzador */}
      <group position={[-0.78, 0, 0.95]} rotation={[0, 0.3, 0]}>
        <Pieza forma="esfera" medidas={[0.13]} color={crema} posicion={[0, 0.1, 0]} escala={[1, 0.75, 1]} />
        <Pieza forma="cilindro" medidas={[0.03, 0.05, 0.06]} color={crema} posicion={[0, 0.21, 0]} />
        <Pieza forma="toro" medidas={[0.035, 0.01]} color={mostaza} posicion={[0, 0.2, 0]} rotacion={[Math.PI / 2, 0, 0]} />
      </group>
      <Pieza forma="caja" medidas={[0.6, 0.04, 0.15]} color={crema} posicion={[0.7, 0.02, 1.0]} rotacion={[0, -0.3, 0]} />
    </group>
  );
};

