import React from 'react';
import {EscenaProps, Pieza, Etiqueta, Ojos, Linea, Aro, aparecer, rebote, flotar, mover, momento, V3} from '../lib3d';

export const Escena0: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, crema, azul, mostaza, suelo] = paleta.acentos;
  const piel = '#E6C3A2';
  const pielSombra = '#D2A987';
  const blancoPelota = '#F3EFE7';
  const metal = '#9EA3A8';

  // Golpes sincronizados con la voz
  const tCrees = momento(palabras, fps, 'crees', 6);
  const tPodrias = momento(palabras, fps, 'podrías', 21);
  const tLanzar = momento(palabras, fps, 'lanzar', 29);
  const tPelota = momento(palabras, fps, 'pelota', 44);
  const tSin = momento(palabras, fps, 'sin', 51);
  const tCosturas = momento(palabras, fps, 'costuras', Math.min(59, duracion - 6));

  const R = 0.36;
  const H: V3 = [-0.05, 0.95, 0];

  // Antes de soltarse: la mano aprieta y la pelota se escurre poco a poco
  const apriete = 0.5 + 0.5 * Math.sin(frame / 2.2);
  const escurre = aparecer(frame, tPodrias, 8);
  const temblor = Math.sin(frame * 1.7) * 0.025 * escurre;
  const suelta = frame >= tLanzar;

  // Trayectoria: sale disparada hacia la cámara y cae delante con bote
  let bx = H[0] + 0.06 * escurre + temblor;
  let by = H[1] + 0.03 * escurre;
  let bz = H[2];
  let giro = 0;
  if (suelta) {
    const f = frame - tLanzar;
    if (f <= 8) {
      const k = f / 8;
      bx = mover(f, [0, 8], [bx, 0.32]);
      by = mover(f, [0, 8], [by, 1.32]);
      bz = mover(f, [0, 8], [0, 1.25]);
      giro = k * 3;
    } else {
      const g = Math.min(1, (f - 8) / 12);
      bx = 0.32 + 0.2 * g;
      bz = 1.25 - 0.45 * g;
      by = 1.32 + (0.38 - 1.32) * g * g + (f > 20 ? Math.abs(Math.sin((f - 20) / 3)) * 0.12 * Math.exp(-(f - 20) / 8) : 0);
      giro = 3 + (f - 8) * 0.18;
    }
  }
  const aplastar = suelta ? 0 : 0.05 * apriete + 0.03 * escurre;
  const ojosPop = 0.7 + 0.3 * rebote(frame, fps, tCrees);

  // La mano se cierra sobre el aire
  const cierre = aparecer(frame, tLanzar, 6);
  const rDedo = R + 0.05 - (R - 0.12) * cierre;
  const sacudida = suelta ? Math.sin((frame - tLanzar) * 1.3) * 0.06 * Math.exp(-(frame - tLanzar) / 10) : 0;

  const dedos = [-0.2, -0.07, 0.06, 0.19];

  // Gotitas de sudor que saltan de la mano
  const gotas = [
    [-0.6, 0.9, 0.3],
    [-0.2, 1.0, 0.5],
    [0.25, 0.9, 0.4],
    [0.5, 0.7, 0.2],
  ];
  const tg = Math.max(0, frame - tPelota);
  const visGotas = aparecer(frame, tPelota, 4);

  // Hilo rojo suelto flotando al lado
  const hilo: V3[] = [];
  for (let i = 0; i <= 18; i++) {
    const t = i / 18;
    hilo.push([
      0.78 + 0.12 * Math.sin(t * 7 + frame * 0.18),
      0.55 + t * 0.95,
      -0.25 + 0.1 * Math.cos(t * 5 + frame * 0.12),
    ]);
  }
  const hiloOnda = 1 + 0.25 * rebote(frame, fps, tCosturas);

  return (
    <group>
      {/* Fondo: tapete del laboratorio, pinzas metálicas y soporte de pelota */}
      <Pieza forma="cilindro" medidas={[1.05, 1.05, 0.02]} color={suelo} posicion={[0, 0.01, 0]} />
      <group position={[-0.85, 0.03, -0.85]} rotation={[0, 0.5, 0]}>
        <Pieza forma="caja" medidas={[0.7, 0.03, 0.05]} color={metal} metal={0.6} posicion={[0, 0, -0.04]} rotacion={[0, 0.08, 0]} />
        <Pieza forma="caja" medidas={[0.7, 0.03, 0.05]} color={metal} metal={0.6} posicion={[0, 0, 0.04]} rotacion={[0, -0.08, 0]} />
        <Pieza forma="cilindro" medidas={[0.05, 0.05, 0.06]} color="#7D8287" posicion={[-0.35, 0.01, 0]} />
      </group>
      <group position={[0.75, 0, -0.85]}>
        <Pieza forma="cilindro" medidas={[0.14, 0.18, 0.05]} color="#4A4E55" posicion={[0, 0.025, 0]} />
        <Pieza forma="cilindro" medidas={[0.03, 0.03, 0.3]} color="#5B6068" posicion={[0, 0.2, 0]} />
        <Pieza forma="cilindro" medidas={[0.07, 0.04, 0.05]} color="#5B6068" posicion={[0, 0.37, 0]} />
      </group>

      {/* Hilo rojo suelto, ya sin pelota */}
      <group scale={[hiloOnda, 1, 1]} position={[0.78 * (1 - hiloOnda), 0, 0]}>
        {hilo.slice(0, -1).map((p, i) => (
          <Linea key={i} desde={p} hasta={hilo[i + 1]} grosor={0.014} color={rojo} />
        ))}
      </group>
      <Pieza forma="esfera" medidas={[0.022]} color={rojo} posicion={hilo[18]} />

      {/* Mano del lanzador */}
      <group position={H} rotation={[0, 0, sacudida]}>
        {/* antebrazo y puño de manga */}
        <Pieza forma="cilindro" medidas={[0.13, 0.15, 0.7]} color={piel} posicion={[-0.82, -0.28, -0.15]} rotacion={[0.2, 0, 1.05]} />
        <Pieza forma="cilindro" medidas={[0.18, 0.18, 0.2]} color={azul} posicion={[-1.0, -0.39, -0.2]} rotacion={[0.2, 0, 1.05]} />
        <Pieza forma="toro" medidas={[0.18, 0.025]} color="#285F9C" posicion={[-0.92, -0.34, -0.18]} rotacion={[0.2, Math.PI / 2, 1.05 - Math.PI / 2]} />
        {/* palma */}
        <Pieza forma="caja" medidas={[0.2, 0.36, 0.46]} color={piel} posicion={[-rDedo - 0.08, 0.02, 0]} rotacion={[0, 0, -0.25 - 0.3 * cierre]} />
        {/* dedos que abrazan la pelota (o el aire) */}
        {dedos.map((z, i) => (
          <group key={i}>
            <Pieza forma="capsula" medidas={[0.055, 0.2]} color={piel} posicion={[-rDedo * 0.45, rDedo * 0.92, z]} rotacion={[0, 0, Math.PI / 2 - 0.35]} />
            <Pieza forma="capsula" medidas={[0.05, 0.12]} color={pielSombra} posicion={[rDedo * 0.6, rDedo * 0.72, z * 0.95]} rotacion={[0, 0, Math.PI / 2 + 0.7 + 0.5 * cierre]} />
          </group>
        ))}
        {/* pulgar por delante */}
        <Pieza forma="capsula" medidas={[0.065, 0.2]} color={piel} posicion={[-rDedo * 0.55, -rDedo * 0.25, rDedo * 0.82]} rotacion={[0.3, 0, -0.9]} />
        <Pieza forma="capsula" medidas={[0.055, 0.1]} color={pielSombra} posicion={[0, -rDedo * 0.35 + 0.05 * cierre, rDedo * 0.95]} rotacion={[0.2, 0, Math.PI / 2]} />
      </group>

      {/* Gotitas de sudor */}
      {gotas.map(([dx, dy, dz], i) => (
        <Pieza
          key={i}
          forma="esfera"
          medidas={[0.035]}
          color="#BFD6E4"
          posicion={[H[0] + dx * (0.35 + tg * 0.025), H[1] + 0.25 + dy * tg * 0.03 - 0.0014 * tg * tg, H[2] + dz * (0.3 + tg * 0.02)]}
          escala={[visGotas, visGotas * 1.45, visGotas]}
        />
      ))}

      {/* La pelota lisa: el protagonista */}
      <group position={[bx, by, bz]} rotation={[giro * 0.6, giro, giro * 0.3]} scale={[1 + aplastar, 1 - aplastar, 1 + aplastar * 0.5]}>
        <Pieza forma="esfera" medidas={[R]} color={blancoPelota} />
        {/* brillo resbaladizo, como jabón */}
        <Pieza forma="esfera" medidas={[0.06]} color="#FFFFFF" contorno={false} posicion={[-0.14, 0.2, 0.24]} escala={[1, 0.6, 0.4]} />
        {[[-0.2, 0.05, 0.29], [0.18, -0.12, 0.29], [0.05, 0.27, 0.22]].map((p, i) => (
          <Pieza key={i} forma="esfera" medidas={[0.025]} color="#CFE0EA" posicion={p as V3} escala={aparecer(frame, tPodrias + i * 3, 5)} />
        ))}
        <Ojos posicion={[0.04, -0.02, R * 0.93]} tam={0.075 * ojosPop} separacion={0.17} mirar={suelta ? [0.2, 0.3] : [-0.7, 0.4]} frame={frame} />
        <Pieza forma="esfera" medidas={[0.035]} color="#2A2420" contorno={false} posicion={[0.04, -0.15, R * 0.96]} escala={[1, 1.3 * ojosPop, 0.5]} />
      </group>
      <Aro posicion={[0.52, 0, 0.8]} radio={0.3} color={rojo} progreso={aparecer(frame, tCosturas, 6)} grosor={0.015} />

      {/* Etiquetas, a los lados y solo con su palabra */}
      <Etiqueta texto="hilo" punto={hilo[12]} desplazamiento={[-0.05, 0.3, 0.2]} escala={aparecer(frame, tSin, 6) * (frame < tCosturas ? 1 : 1 - aparecer(frame, tCosturas + 4, 4))} />
      <Etiqueta texto="sin costuras" punto={[0.6, 0.62, 0.85]} desplazamiento={[-0.2, 0.75, 0.1]} color="#FFFFFF" escala={aparecer(frame, tCosturas, 5)} />

      {/* Capa delantera: bolsa de resina del lanzador */}
      <group position={[-0.7, 0, 0.85]} rotation={[0, flotar(frame, 0.05, 90), 0]}>
        <Pieza forma="esfera" medidas={[0.13]} color={crema} posicion={[0, 0.1, 0]} escala={[1, 0.7, 1]} />
        <Pieza forma="cilindro" medidas={[0.03, 0.05, 0.06]} color={crema} posicion={[0, 0.2, 0]} />
        <Pieza forma="toro" medidas={[0.035, 0.01]} color={mostaza} posicion={[0, 0.2, 0]} rotacion={[Math.PI / 2, 0, 0]} />
      </group>
    </group>
  );
};

escenas.Escena2:
import React from 'react';
import {interpolate, Easing} from 'remotion';
import * as THREE from 'three';
import {EscenaProps, Pieza, Etiqueta, Linea, Aro, Brillo, aparecer, flotar, momento, V3} from '../lib3d';

// ---------- Geometría fija de la pelota y sus 108 puntadas ----------
const R = 0.55;
const N = 108;
const CENTRO = new THREE.Vector3(0, 0.8, 0);

const costura = (t: number) => {
  const a = 0.65;
  const b = 0.35;
  const c = 2 * Math.sqrt(a * b);
  return new THREE.Vector3(a * Math.cos(t) + b * Math.cos(3 * t), a * Math.sin(t) - b * Math.sin(3 * t), c * Math.sin(2 * t)).normalize();
};
const tup = (v: THREE.Vector3): V3 => [v.x, v.y, v.z];

const PUNTADAS = Array.from({length: N}, (_, i) => {
  const t = (i / N) * Math.PI * 2;
  const p = costura(t);
  const T = costura(t + 0.01).sub(costura(t - 0.01)).normalize();
  const B = p.clone().cross(T).normalize();
  const base = p.clone().multiplyScalar(R * 1.012);
  const pierna = (lado: number): [V3, V3] => [
    tup(base.clone().add(B.clone().multiplyScalar(0.055 * lado)).add(T.clone().multiplyScalar(-0.011))),
    tup(base.clone().add(B.clone().multiplyScalar(0.012 * lado)).add(T.clone().multiplyScalar(0.012))),
  ];
  const t2 = ((i + 1) / N) * Math.PI * 2;
  return {
    local: p.clone().multiplyScalar(R),
    izq: pierna(1),
    der: pierna(-1),
    surco: [tup(p.clone().multiplyScalar(R * 1.003)), tup(costura(t2).multiplyScalar(R * 1.003))] as [V3, V3],
  };
});

// La costura empieza (puntada 0) en el lado que mira a la cámara, arriba a la izquierda.
const U = new THREE.Vector3(-0.55, 0.35, 0.75).normalize();
const Q_PELOTA = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(1, 0, 0), U);
const W_PINZA = U.clone().add(new THREE.Vector3(0, 0.9, 0)).normalize();
const Q_PINZA = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), W_PINZA);
const aMundo = (v: THREE.Vector3) => v.clone().applyQuaternion(Q_PELOTA).add(CENTRO);

const clamp = {extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const};

export const Escena2: React.FC<EscenaProps> = ({frame, fps, palabras, paleta}) => {
  const [rojo, crema, azul, mostaza, suelo] = paleta.acentos;
  const blancoPelota = '#F3EFE6';
  const hilo = '#A9483A';
  const metalPinza = '#A7ABB0';
  const madera = '#A9845C';

  // Golpes sincronizados con la voz
  const tAsi = momento(palabras, fps, 'así', 1);
  const tVamos = momento(palabras, fps, 'vamos', 16);
  const tQuitar = momento(palabras, fps, 'quitárselas', 31);
  const tLisa = momento(palabras, fps, 'lisa', 76);
  const tBlanca = momento(palabras, fps, 'blanca', 91);
  const finTiron = tQuitar + 30;

  // Pinzas: se acercan, cierran y tiran del hilo
  const acerca = interpolate(frame, [tAsi, tQuitar - 3], [0.45, 0.01], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const pr = interpolate(frame, [tQuitar, finTiron], [0, 1], {...clamp, easing: Easing.inOut(Easing.quad)});
  const distancia = acerca + pr * 0.5;
  const punta = CENTRO.clone().add(U.clone().multiplyScalar(R + distancia));
  const abre = interpolate(frame, [tAsi, tVamos, tQuitar - 4, tQuitar - 1], [0.03, 0.1, 0.1, 0.012], clamp);
  const tiembla = frame >= tQuitar && frame < finTiron ? Math.sin(frame * 1.7) * 0.01 : 0;

  // Puntadas que ya salieron
  const quitadas = Math.floor(pr * N);
  const puntoHilo = quitadas < N ? aMundo(PUNTADAS[quitadas].local) : punta;

  // Momento "lisa": rebote suave, brillo y destellos
  const fl = frame - tLisa;
  const pulso = fl >= 0 ? Math.exp(-fl / 6) * Math.sin(fl / 2) : 0;
  const brilloPelota = aparecer(frame, tLisa, 8) * (0.18 + 0.06 * Math.sin(frame / 4));
  const aro = aparecer(frame, tLisa + 2, 14);
  const aroBlanca = aparecer(frame, tBlanca, 6);

  const hiloEtq = aparecer(frame, tQuitar + 4, 8) * (1 - aparecer(frame, tLisa - 6, 5));
  const lisaEtq = aparecer(frame, tLisa, 8);

  const destellos: V3[] = [
    [0.32, 1.3, 0.32],
    [-0.08, 1.42, 0.28],
    [0.52, 0.98, 0.38],
    [0.12, 1.12, 0.58],
  ];

  return (
    <group>
      {/* ---------- Fondo: tapete de laboratorio y bate ---------- */}
      <Pieza forma="caja" medidas={[2.1, 0.012, 1.9]} color={suelo} posicion={[0, 0.006, 0]} />
      {[-0.75, -0.45, -0.15, 0.15, 0.45, 0.75].map((x) => (
        <Linea key={`gx${x}`} desde={[x, 0.014, -0.95]} hasta={[x, 0.014, 0.95]} grosor={0.003} color="#A69F93" />
      ))}
      {[-0.75, -0.45, -0.15, 0.15, 0.45, 0.75].map((z) => (
        <Linea key={`gz${z}`} desde={[-1.05, 0.014, z]} hasta={[1.05, 0.014, z]} grosor={0.003} color="#A69F93" />
      ))}
      <group position={[0.35, 0.06, -0.95]} rotation={[0, 0.35, Math.PI / 2]}>
        <Pieza forma="cilindro" medidas={[0.055, 0.02, 1.3]} color="#B48A5A" />
        <Pieza forma="cilindro" medidas={[0.032, 0.032, 0.03]} color="#8C6A45" posicion={[0, -0.66, 0]} />
        <Pieza forma="cilindro" medidas={[0.024, 0.024, 0.26]} color="#3A3A40" posicion={[0, -0.5, 0]} />
      </group>
      <Pieza forma="esfera" medidas={[0.11]} color={crema} posicion={[-0.7, 0.11, -0.75]} />

      {/* ---------- Medio: base de exhibición y pelota ---------- */}
      <Pieza forma="caja" medidas={[1.25, 0.08, 0.95]} color={madera} posicion={[0, 0.05, 0]} />
      <Pieza forma="caja" medidas={[1.1, 0.02, 0.8]} color="#B9946A" posicion={[0, 0.1, 0]} />
      <Pieza forma="cilindro" medidas={[0.2, 0.26, 0.16]} color={crema} posicion={[0, 0.19, 0]} />
      <Pieza forma="toro" medidas={[0.2, 0.025]} color="#C9C2B6" posicion={[0, 0.27, 0]} rotacion={[Math.PI / 2, 0, 0]} />
      <Aro posicion={[0, 0.11, 0]} radio={0.62} color={azul} progreso={aro} grosor={0.018 + 0.008 * aroBlanca} />

      <group position={[0, 0.8 + 0.05 * pulso, 0]} scale={[1 + 0.05 * pulso, 1 - 0.05 * pulso, 1 + 0.05 * pulso]}>
        <group quaternion={Q_PELOTA}>
          <Pieza forma="esfera" medidas={[R]} color={blancoPelota} brillo={brilloPelota > 0.01 ? '#FFFFFF' : undefined} />
          {PUNTADAS.map((p, i) =>
            i >= quitadas ? (
              <group key={i}>
                <Linea desde={p.surco[0]} hasta={p.surco[1]} grosor={0.004} color="#CFC6B6" />
                <Linea desde={p.izq[0]} hasta={p.izq[1]} grosor={0.009} color={hilo} />
                <Linea desde={p.der[0]} hasta={p.der[1]} grosor={0.009} color={hilo} />
              </group>
            ) : null,
          )}
        </group>
      </group>

      {/* Hilo rojo que sale tirado por las pinzas */}
      {frame >= tQuitar - 2 && quitadas < N ? (
        <Linea desde={tup(punta)} hasta={tup(puntoHilo)} grosor={0.009} color={hilo} />
      ) : null}
      {frame >= finTiron ? (
        <Linea
          desde={tup(punta)}
          hasta={[punta.x + flotar(frame, 0.06, 40), punta.y - 0.32, punta.z + 0.03]}
          grosor={0.009}
          color={hilo}
        />
      ) : null}

      {/* Pinzas metálicas gigantes */}
      <group position={[punta.x + tiembla, punta.y, punta.z]} quaternion={Q_PINZA}>
        <group position={[0, 0.72, 0]}>
          {[-1, 1].map((l) => (
            <group key={l} rotation={[0, 0, abre * l]}>
              <Pieza forma="caja" medidas={[0.04, 0.72, 0.018]} color={metalPinza} metal={0.6} posicion={[0, -0.36, 0]} />
              <Pieza forma="caja" medidas={[0.042, 0.16, 0.022]} color="#8E9297" metal={0.6} posicion={[0, -0.32, 0]} />
              <Pieza forma="caja" medidas={[0.042, 0.03, 0.022]} color="#7E8287" metal={0.6} posicion={[0, -0.22, 0]} />
              <Pieza forma="caja" medidas={[0.042, 0.03, 0.022]} color="#7E8287" metal={0.6} posicion={[0, -0.42, 0]} />
            </group>
          ))}
          <Pieza forma="caja" medidas={[0.07, 0.06, 0.03]} color="#8E9297" metal={0.6} posicion={[0, 0.02, 0]} />
        </group>
      </group>

      {/* Destellos de pelota lisa */}
      {destellos.map((d, i) => {
        const s = aparecer(frame, tLisa + i * 3, 6) * (0.6 + 0.4 * Math.sin(frame / 3 + i * 1.7));
        return s > 0.02 ? <Brillo key={i} posicion={d} color="#FFFFFF" radio={0.03 * s} /> : null;
      })}

      {/* ---------- Etiquetas ---------- */}
      <Etiqueta texto="hilo rojo" punto={tup(punta)} desplazamiento={[0.05, 0.32, 0]} escala={hiloEtq} />
      <Etiqueta texto="pelota lisa" punto={[0.38, 1.12, 0.25]} desplazamiento={[0.32, 0.45, 0.05]} escala={lisaEtq} color="#FFFFFF" />

      {/* ---------- Delante: carrete del hilo ---------- */}
      <group position={[0.72, 0, 0.72]} rotation={[0, -0.4, 0]}>
        <Pieza forma="cilindro" medidas={[0.11, 0.11, 0.025]} color={madera} posicion={[0, 0.0125, 0]} />
        <Pieza forma="cilindro" medidas={[0.085, 0.085, 0.16]} color={rojo} posicion={[0, 0.105, 0]} />
        <Pieza forma="cilindro" medidas={[0.11, 0.11, 0.025]} color={madera} posicion={[0, 0.2, 0]} />
        <Pieza forma="cilindro" medidas={[0.02, 0.02, 0.03]} color={mostaza} posicion={[0, 0.225, 0]} />
      </group>
    </group>
  );
};

