import React from 'react';
import {EscenaProps, Pieza, Etiqueta, Flecha, Ojos, Aro, Linea, aparecer, desaparecer, rebote, flotar, mover, momento, V3} from '../lib3d';

const R = 0.12;
// Curva real de la costura de béisbol sobre una esfera unitaria
const costura: V3[] = Array.from({length: 28}, (_, i) => {
  const t = (i / 28) * Math.PI * 2;
  const x = (9 * Math.cos(t) - 4 * Math.cos(3 * t)) / 13;
  const y = (9 * Math.sin(t) + 4 * Math.sin(3 * t)) / 13;
  const z = (12 / 13) * Math.sin(2 * t);
  const k = R * 1.01;
  return [x * k, y * k, z * k];
});

const bez = (S: V3, C: V3, E: V3, u: number): V3 => {
  const a = (1 - u) * (1 - u);
  const b = 2 * u * (1 - u);
  const c = u * u;
  return [a * S[0] + b * C[0] + c * E[0], a * S[1] + b * C[1] + c * E[1], a * S[2] + b * C[2] + c * E[2]];
};

const Pelota: React.FC<{posicion: V3; giro: V3; escala: number; frame: number; mirar: [number, number]}> = ({posicion, giro, escala, frame, mirar}) => (
  <group position={posicion} scale={escala}>
    <group rotation={giro}>
      <Pieza forma="esfera" medidas={[R]} color="#F2EEE6" />
      {costura.map((p, i) => {
        const q = costura[(i + 1) % costura.length];
        return <Linea key={i} desde={p} hasta={q} grosor={0.004} color="#B9573F" />;
      })}
      {costura.filter((_, i) => i % 2 === 0).map((p, i) => (
        <Pieza key={`p${i}`} forma="caja" medidas={[0.022, 0.006, 0.006]} color="#A8452F" posicion={p} rotacion={[0, 0, i * 0.7]} contorno={false} />
      ))}
    </group>
    <group rotation={[0, -0.7, 0]}>
      <Ojos posicion={[0, 0.02, R * 0.92]} tam={0.028} separacion={0.07} mirar={mirar} frame={frame} />
    </group>
  </group>
);

export const Escena6: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, crema, azul, mostaza] = paleta.acentos;
  const piel = '#E8C4A2';
  const manga = '#3E5C86';
  const grisCalido = '#8A847A';

  const tLances = momento(palabras, fps, 'lances', 35);
  const tApuntan = momento(palabras, fps, 'apunten', 65);
  const tPelota = momento(palabras, fps, 'pelota', 104);
  const tDistinto = momento(palabras, fps, 'distinto', 124);
  const tAire = momento(palabras, fps, 'aire', Math.round(duracion * 0.88));

  // Primer golpe: las pelotas dan un saltito en la mano desde el fotograma 0
  const pop = 0.85 + 0.15 * rebote(frame, fps, 1);
  // Mano: carga hacia atrás y suelta
  const carga = mover(frame, [tLances, tLances + 14], [0, 1]);
  const suelta = mover(frame, [tPelota - 6, tPelota + 4], [0, 1]);
  const dx = -0.08 * carga + 0.18 * suelta;
  const giroMano = 0.3 * carga - 0.75 * suelta;

  const S: V3 = [-0.68, 1.12, 0.3];
  const viaje = Math.min(1, Math.max(0, (frame - tPelota) / 24));
  const u = 1 - Math.pow(1 - viaje, 2);
  const resalto = aparecer(frame, tDistinto, 10);

  const caminos: {C: V3; E: V3; col: string; giroFin: V3; spin: V3; off: V3}[] = [
    {C: [0.05, 1.2, 0.05], E: [0.8, 1.25, -0.25], col: grisCalido, giroFin: [0, 0, 0], spin: [1, 0, 0], off: [0.02, 0.11, 0]},
    {C: [0.15, 1.2, -0.8], E: [0.72, 1.0, 0.55], col: azul, giroFin: [0.9, 0, 0.7], spin: [0, 1, 0.3], off: [0.03, -0.04, 0.13]},
    {C: [0.1, 1.42, 0.15], E: [0.8, 0.32, 0.05], col: mostaza, giroFin: [-1.2, 0.4, 0], spin: [0, 0, 1], off: [0.03, -0.05, -0.13]},
  ];
  const orienta = mover(frame, [tApuntan, tApuntan + 12], [0, 1]);

  return (
    <group>
      {/* Fondo: zona de strike con red al final del recorrido */}
      <group position={[0.55, 0, -0.95]}>
        {[-0.45, 0.45].map((x) => (
          <Pieza key={x} forma="caja" medidas={[0.05, 1.6, 0.05]} color={grisCalido} posicion={[x, 0.8, 0]} />
        ))}
        <Pieza forma="caja" medidas={[0.95, 0.05, 0.05]} color={grisCalido} posicion={[0, 1.6, 0]} />
        {[0.4, 0.75, 1.1, 1.45].map((y) => (
          <Linea key={y} desde={[-0.43, y, 0]} hasta={[0.43, y, 0]} grosor={0.005} color="#6E685F" />
        ))}
        {[-0.2, 0, 0.2].map((x) => (
          <Linea key={`v${x}`} desde={[x, 0.05, 0]} hasta={[x, 1.58, 0]} grosor={0.005} color="#6E685F" />
        ))}
        <Pieza forma="caja" medidas={[0.4, 0.02, 0.4]} color={crema} posicion={[0, 0.01, 0.35]} rotacion={[0, Math.PI / 4, 0]} />
      </group>

      {/* Medio: montículo bajo la mano */}
      <Pieza forma="cilindro" medidas={[0.55, 0.62, 0.06]} color="#B8A58C" posicion={[-0.7, 0.03, 0.3]} />
      <Pieza forma="caja" medidas={[0.3, 0.03, 0.08]} color={crema} posicion={[-0.7, 0.075, 0.3]} />

      {/* La mano del lanzador */}
      <group position={[-0.86 + dx, 1.08, 0.3]} rotation={[0, 0, giroMano]}>
        <Pieza forma="cilindro" medidas={[0.1, 0.12, 0.42]} color={manga} posicion={[-0.32, -0.02, 0]} rotacion={[0, 0, Math.PI / 2]} />
        <Pieza forma="toro" medidas={[0.1, 0.025]} color="#2F4A6E" posicion={[-0.11, -0.02, 0]} rotacion={[0, Math.PI / 2, 0]} />
        <Pieza forma="caja" medidas={[0.14, 0.24, 0.34]} color={piel} posicion={[0, 0, 0]} />
        {[-0.12, -0.04, 0.04, 0.12].map((z, i) => (
          <Pieza key={z} forma="capsula" medidas={[0.032, 0.12]} color={piel} posicion={[0.12, 0.13 - i * 0.005, z]} rotacion={[0, 0, -1.1]} />
        ))}
        <Pieza forma="capsula" medidas={[0.035, 0.1]} color={piel} posicion={[0.1, -0.13, 0.05]} rotacion={[0, 0, -2.0]} />
      </group>

      {/* Trayectorias punteadas */}
      {caminos.map((c, k) =>
        Array.from({length: 14}, (_, i) => {
          const f = (i + 1) / 15;
          if (f > u) return null;
          const p = bez(S, c.C, c.E, f);
          return <Pieza key={`${k}-${i}`} forma="esfera" medidas={[0.016 + 0.008 * resalto]} color={c.col} posicion={p} contorno={false} />;
        }),
      )}

      {/* Las tres pelotas */}
      {caminos.map((c, k) => {
        const enMano: V3 = [S[0] + c.off[0] + dx, S[1] + c.off[1], S[2] + c.off[2]];
        const vuelo = bez(S, c.C, c.E, u);
        const pos: V3 = frame < tPelota ? enMano : [vuelo[0], vuelo[1] + flotar(frame + k * 20, 0.01, 50) * viaje, vuelo[2]];
        const s = Math.max(0, frame - tPelota) * 0.35;
        const giro: V3 = [
          c.giroFin[0] * orienta + c.spin[0] * s * (1 - viaje * 0.7),
          c.giroFin[1] * orienta + c.spin[1] * s * (1 - viaje * 0.7),
          c.giroFin[2] * orienta + c.spin[2] * s * (1 - viaje * 0.7),
        ];
        const mira: [number, number] = [mover(frame, [tPelota, tPelota + 8], [0, 0.8]), k === 2 ? -0.6 * viaje : 0];
        return <Pelota key={k} posicion={pos} giro={giro} escala={pop * (1 + 0.15 * resalto * (k === 1 ? 1 : 0.4))} frame={frame + k * 30} mirar={mira} />;
      })}

      {/* Llegada: aros en los tres destinos */}
      {caminos.map((c, k) => (
        <Aro key={`a${k}`} posicion={[c.E[0], 0, c.E[2]]} radio={0.1} color={c.col} progreso={aparecer(frame, tDistinto + k * 3, 10)} />
      ))}

      {/* Aire desviado por las costuras */}
      {[0, 1].map((i) => (
        <Flecha
          key={`f${i}`}
          desde={[0.25, 1.32 - i * 0.14, -0.55 + i * 0.1]}
          hasta={[0.6, 1.22 - i * 0.14, -0.05 + i * 0.1]}
          color="#9CC3E6"
          grosor={0.014}
          progreso={mover(frame, [tAire + i * 3, tAire + i * 3 + 10], [0, 1])}
        />
      ))}

      {/* Textos */}
      <Etiqueta
        texto="costuras"
        punto={[S[0] + 0.05, S[1] + 0.2, S[2]]}
        desplazamiento={[0.1, 0.42, 0]}
        escala={aparecer(frame, tApuntan + 4, 8) * (1 - desaparecer(frame, tPelota - 4, 8))}
      />
      <Etiqueta texto="tres caminos" punto={bez(S, caminos[0].C, caminos[0].E, 0.6)} desplazamiento={[0.05, 0.42, 0]} color="#FFFFFF" escala={resalto} />

      {/* Delante: pelota de repuesto en el suelo */}
      <group rotation={[0, frame * 0.01, 0]}>
        <Pelota posicion={[0.35, R, 0.85]} giro={[0.4, 0.8, 0]} escala={1} frame={frame + 50} mirar={[0.4, 0.3]} />
      </group>
    </group>
  );
};

