import React from 'react';
import * as THREE from 'three';
import {EscenaProps, Pieza, Etiqueta, Linea, Aro, aparecer, flotar, mover, momento} from '../lib3d';

// ---------- Costura de béisbol (curva doble cerrada sobre la esfera) ----------
const R = 0.6;
const K = 0.2;
const puntoCostura = (t: number) =>
  new THREE.Vector3(
    (1 - K) * Math.cos(t) + K * Math.cos(3 * t),
    (1 - K) * Math.sin(t) - K * Math.sin(3 * t),
    2 * Math.sqrt(K * (1 - K)) * Math.sin(2 * t),
  ).normalize();

const curva = new THREE.CatmullRomCurve3(
  Array.from({length: 160}, (_, i) => puntoCostura((i / 160) * Math.PI * 2).multiplyScalar(R * 1.004)),
  true,
);
const geoCostura = new THREE.TubeGeometry(curva, 240, 0.011, 6, true);
const geoPuntada = new THREE.CapsuleGeometry(0.009, 0.042, 4, 8);

type Puntada = {pos: THREE.Vector3; q: THREE.Quaternion};
const PUNTADAS: Puntada[] = (() => {
  const lista: Puntada[] = [];
  const N = 54;
  const eje = new THREE.Vector3(0, 1, 0);
  for (let i = 0; i < N; i++) {
    const t = (i / N) * Math.PI * 2;
    const p = puntoCostura(t);
    const tan = puntoCostura(t + 0.002).sub(puntoCostura(t - 0.002)).normalize();
    const lado = new THREE.Vector3().crossVectors(tan, p).normalize();
    [-1, 1].forEach((s) => {
      const dir = lado.clone().multiplyScalar(s).add(tan.clone().multiplyScalar(0.6)).normalize();
      const pos = p.clone().multiplyScalar(R * 1.012).add(lado.clone().multiplyScalar(s * 0.028));
      lista.push({pos, q: new THREE.Quaternion().setFromUnitVectors(eje, dir)});
    });
  }
  return lista;
})();

// Segmento de dedo en el plano XY (cápsula entre dos puntos)
const Segmento: React.FC<{a: [number, number]; b: [number, number]; z: number; r: number; color: string}> = ({a, b, z, r, color}) => {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const largo = Math.max(0.01, Math.hypot(dx, dy));
  return (
    <Pieza forma="capsula" medidas={[r, largo]} color={color}
      posicion={[(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, z]} rotacion={[0, 0, Math.atan2(dy, dx) - Math.PI / 2]} />
  );
};

// Punto sobre la superficie (radio de apoyo del dedo) a un ángulo dado
const sobre = (grados: number, z: number, rr = 0.655): [number, number] => {
  const r = Math.sqrt(Math.max(0.01, rr * rr - z * z));
  const a = (grados * Math.PI) / 180;
  return [r * Math.cos(a), 0.85 + r * Math.sin(a)];
};

const Dedo: React.FC<{angulos: number[]; z: number; r: number; color: string}> = ({angulos, z, r, color}) => (
  <group>
    {angulos.slice(0, -1).map((g, i) => (
      <Segmento key={i} a={sobre(g, z)} b={sobre(angulos[i + 1], z)} z={z} r={r * (1 - i * 0.06)} color={color} />
    ))}
  </group>
);

// Flecha curva (arco con punta)
const ArcoFlecha: React.FC<{radio: number; arco: number; color: string; grosor?: number}> = ({radio, arco, color, grosor = 0.028}) => {
  const a = Math.round(arco * 20) / 20;
  if (a <= 0.05) return null;
  return (
    <group>
      <Pieza forma="toro" medidas={[radio, grosor, a]} color={color} />
      <Pieza forma="cono" medidas={[grosor * 2.6, grosor * 6]} color={color}
        posicion={[radio * Math.cos(a), radio * Math.sin(a), 0]} rotacion={[0, 0, a]} />
    </group>
  );
};

export const Escena4: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, crema, azul, mostaza] = paleta.acentos;
  const cuero = '#EFEBE2';
  const piel = '#E6C3A5';
  const manga = '#3E4D66';
  const metal = '#8E9196';
  const metalOscuro = '#5F6266';

  const tCosturas = momento(palabras, fps, 'costuras', 8);
  const tDedos = momento(palabras, fps, 'dedos', 23);
  const tEngancha = momento(palabras, fps, 'enganchan', 38);
  const tGiro = momento(palabras, fps, 'giro', 68);
  const tPelota = momento(palabras, fps, 'pelota', 99);
  const tExtra = Math.min(tPelota + 45, duracion - 40);

  // Golpe 1: las costuras laten
  const fc = frame - tCosturas;
  const pulso = fc >= 0 && fc < 14 ? Math.sin((fc / 14) * Math.PI) : 0;
  const escPuntada = 1 + 0.6 * pulso;

  // Golpe 2: la mano entra, se apoya y presiona
  const entra = mover(frame, [tDedos - 6, tDedos + 8], [1, 0]);
  const fe = frame - tEngancha;
  const presion = fe >= 0 && fe < 12 ? Math.sin((fe / 12) * Math.PI) * 0.025 : 0;
  const suelta = mover(frame, [tGiro - 2, tGiro + 8], [0, 1]);
  const manoX = 0.55 * entra + 0.75 * suelta;
  const manoY = -0.1 * entra - presion - 0.4 * suelta;
  const manoRot = -0.35 * suelta;
  const contacto = aparecer(frame, tEngancha, 8) * (1 - aparecer(frame, tGiro - 2, 5));

  // Golpe 3: la pelota gira
  const fg = Math.max(0, frame - tGiro);
  const giro = 0.3 * fg * Math.min(1, fg / 14);
  const arcos = aparecer(frame, tGiro, 14);
  const extraGiro = aparecer(frame, tExtra, 12);
  const aire = aparecer(frame, tPelota, 12);

  const etAgarre = aparecer(frame, tEngancha + 3, 8) * (1 - aparecer(frame, tGiro, 6));
  const etGiro = aparecer(frame, tGiro + 4, 8);

  return (
    <group>
      {/* Tapete del laboratorio */}
      <Pieza forma="caja" medidas={[2.0, 0.02, 1.7]} color="#B4ADA2" posicion={[0, 0.01, 0]} contorno={false} />

      {/* Fondo: soporte con pinza que sostiene una pelota lisa (la de antes) */}
      <group position={[-0.95, 0, -1.05]}>
        <Pieza forma="cilindro" medidas={[0.16, 0.18, 0.04]} color={metalOscuro} posicion={[0, 0.02, 0]} />
        <Pieza forma="cilindro" medidas={[0.02, 0.02, 1.0]} color={metal} posicion={[0, 0.52, 0]} metal={0.6} />
        <Pieza forma="caja" medidas={[0.3, 0.035, 0.035]} color={metal} posicion={[0.15, 0.95, 0]} />
        <Pieza forma="caja" medidas={[0.04, 0.12, 0.08]} color={metalOscuro} posicion={[0.3, 0.88, 0]} />
        <Pieza forma="esfera" medidas={[0.2]} color={cuero} posicion={[0.3, 0.63, 0]} />
      </group>
      <Pieza forma="caja" medidas={[0.42, 0.05, 0.3]} color={crema} posicion={[1.05, 0.05, -1.0]} rotacion={[0, -0.4, 0]} />
      <Pieza forma="esfera" medidas={[0.12]} color={cuero} posicion={[1.05, 0.2, -1.0]} />

      {/* Soporte bajo la pelota principal */}
      <Pieza forma="cilindro" medidas={[0.26, 0.3, 0.05]} color={metalOscuro} posicion={[0, 0.025, 0]} />
      <Pieza forma="cilindro" medidas={[0.05, 0.05, 0.2]} color={metal} posicion={[0, 0.15, 0]} metal={0.6} />
      <Pieza forma="toro" medidas={[0.16, 0.025]} color={metal} posicion={[0, 0.28, 0]} rotacion={[Math.PI / 2, 0, 0]} />
      <Aro posicion={[0, 0.05, 0]} radio={0.42} color={mostaza} progreso={extraGiro} grosor={0.018} />

      {/* Corriente de aire detrás de la pelota */}
      {aire > 0.01
        ? [0.35, 0.6, 1.1, 1.35, 1.6].map((y, i) => {
            const x = ((frame * 0.035 + i * 0.53) % 2.2) - 1.1;
            const desvio = x > 0 ? -0.08 * x * Math.sign(y - 0.85) : 0;
            return (
              <Linea key={i} desde={[x, y, -0.7]} hasta={[x + 0.38, y + desvio, -0.7]} grosor={0.012}
                color="#9DB8D6" progreso={aire} />
            );
          })
        : null}

      {/* La pelota con costuras */}
      <group position={[0, 0.85 + flotar(frame, 0.012, 70), 0]} rotation={[0.25, -0.2, 0]}>
        <group rotation={[0, 0, giro]}>
          <Pieza forma="esfera" medidas={[R]} color={cuero} />
          <mesh geometry={geoCostura} castShadow>
            <meshToonMaterial color="#9A4434" />
          </mesh>
          {PUNTADAS.map((p, i) => (
            <mesh key={i} geometry={geoPuntada} position={p.pos} quaternion={p.q} scale={escPuntada}>
              <meshToonMaterial color={rojo} />
            </mesh>
          ))}
        </group>
      </group>

      {/* Flechas curvas del giro */}
      <group position={[0, 0.85, 0.12]} rotation={[0, 0, giro * 0.35]}>
        {[0, Math.PI].map((r, i) => (
          <group key={i} rotation={[0, 0, r + 0.3]}>
            <ArcoFlecha radio={0.8} arco={1.7 * arcos + 0.4 * extraGiro} color={azul} />
          </group>
        ))}
      </group>

      {/* Mano del lanzador: dedos sobre las costuras */}
      <group position={[manoX, manoY, 0]} rotation={[0, 0, manoRot]}>
        <Pieza forma="esfera" medidas={[0.2]} color={piel} posicion={[0.8, 0.92, 0.03]} escala={[0.55, 1.15, 0.95]} />
        <Dedo angulos={[28, 58, 88, 110]} z={0.1} r={0.052} color={piel} />
        <Dedo angulos={[30, 60, 90, 113]} z={-0.06} r={0.052} color={piel} />
        <Dedo angulos={[-18, -45, -68]} z={0.13} r={0.056} color={piel} />
        <Dedo angulos={[24, 48, 70]} z={-0.19} r={0.042} color={piel} />
        <Pieza forma="cilindro" medidas={[0.15, 0.15, 0.26]} color={manga} posicion={[1.1, 0.82, 0.03]} rotacion={[0, 0, Math.PI / 2 + 0.3]} />
        <Pieza forma="toro" medidas={[0.15, 0.025]} color="#2E3A4E" posicion={[0.98, 0.86, 0.03]} rotacion={[0, Math.PI / 2, 0.3]} />
        <Pieza forma="cilindro" medidas={[0.17, 0.2, 0.5]} color={manga} posicion={[1.42, 0.72, 0.03]} rotacion={[0, 0, Math.PI / 2 + 0.3]} />
        {/* Puntos donde los dedos se enganchan en la costura */}
        {contacto > 0.01
          ? [0.1, -0.06].map((z, i) => {
              const [x, y] = sobre(92, z, 0.61);
              return (
                <Pieza key={i} forma="toro" medidas={[0.07, 0.012]} color={azul} contorno={false}
                  posicion={[x, y + 0.01, z]} rotacion={[Math.PI / 2, 0, 0]} escala={contacto} />
              );
            })
          : null}
      </group>

      {/* Etiquetas */}
      <Etiqueta texto="agarre" punto={[-0.22, 1.46, 0.1]} desplazamiento={[-0.48, 0.28, 0.15]} escala={etAgarre} />
      <Etiqueta texto="giro" punto={[-0.8, 0.95, 0.12]} desplazamiento={[-0.15, 0.6, 0.2]} escala={etGiro} color={crema} />

      {/* Delante: bolsa de resina del lanzador */}
      <group position={[0.7, 0, 0.95]}>
        <Pieza forma="esfera" medidas={[0.13]} color="#E3DDD0" posicion={[0, 0.08, 0]} escala={[1, 0.6, 1]} />
        <Pieza forma="cilindro" medidas={[0.03, 0.05, 0.06]} color="#D8D0C0" posicion={[0, 0.17, 0]} />
        <Pieza forma="toro" medidas={[0.035, 0.008]} color={rojo} posicion={[0, 0.15, 0]} rotacion={[Math.PI / 2, 0, 0]} />
      </group>
    </group>
  );
};

escenas.Escena5:
import React from 'react';
import * as THREE from 'three';
import {EscenaProps, Pieza, Etiqueta, Linea, Ojos, Bloque, aparecer, flotar, mover, momento} from '../lib3d';

// ---------- Geometría fija de la pelota (calculada una sola vez) ----------
const R = 0.5; // radio de la pelota gigante
const CY = 1.0; // altura del centro
const A = 0.7;
const B = 0.3;
const puntosCostura: THREE.Vector3[] = [];
for (let i = 0; i < 160; i++) {
  const t = (i / 160) * Math.PI * 2;
  const v = new THREE.Vector3(
    A * Math.cos(t) + B * Math.cos(3 * t),
    A * Math.sin(t) - B * Math.sin(3 * t),
    2 * Math.sqrt(A * B) * Math.sin(2 * t),
  ).normalize();
  puntosCostura.push(v.multiplyScalar(R * 1.004));
}
const curvaCostura = new THREE.CatmullRomCurve3(puntosCostura, true);
const tuboCostura = new THREE.TubeGeometry(curvaCostura, 320, 0.009, 6, true);

type Brazo = [[number, number, number], [number, number, number]];
const puntadas: Brazo[] = [];
const N_PUNTADAS = 64;
for (let k = 0; k < N_PUNTADAS; k++) {
  const u = k / N_PUNTADAS;
  const p = curvaCostura.getPointAt(u);
  const T = curvaCostura.getTangentAt(u).normalize();
  const Nn = p.clone().normalize();
  const S = T.clone().cross(Nn).normalize();
  const alto = Nn.clone().multiplyScalar(0.007);
  const punta = p.clone().add(T.clone().multiplyScalar(0.022)).add(alto);
  [1, -1].forEach((lado) => {
    const ext = p.clone().add(S.clone().multiplyScalar(0.04 * lado)).sub(T.clone().multiplyScalar(0.006)).add(alto);
    puntadas.push([
      [ext.x, ext.y, ext.z],
      [punta.x, punta.y, punta.z],
    ]);
  });
}

const pulso = (f: number, t: number) => (f < t ? 0 : Math.exp(-(f - t) / 6) * Math.sin((f - t) / 2));

export const Escena5: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, crema, azul, mostaza] = paleta.acentos;
  const cuero = '#F3EFE7';
  const metal = '#9EA2A6';
  const metalOscuro = '#6F7377';
  const celeste = '#A9CBE8';
  const celesteTenue = '#CADCEB';
  const pared = '#3A4A63';
  const rejilla = '#4C5D79';

  // Golpes con la voz
  const tSeg = momento(palabras, fps, 'Segundo', 1);
  const tProb = momento(palabras, fps, 'problema', Math.round(fps * 0.55));
  const tCost = momento(palabras, fps, 'costuras', Math.round(fps * 1.45));
  const tCamb = momento(palabras, fps, 'cambian', Math.round(fps * 2.23));
  const tAire = momento(palabras, fps, 'aire', Math.round(fps * 3.27));
  const tSup = momento(palabras, fps, 'superficie', Math.round(Math.min(duracion - 10, fps * 3.95)));

  // Pelota: pequeño aplastamiento al inicio y sacudida al nombrar las costuras
  const p1 = pulso(frame, tSeg);
  const p2 = pulso(frame, tCost);
  const aplasta = 0.05 * p1 + 0.04 * p2;
  const sacudida = 0.08 * p2;
  const grosorPuntada = 0.0075 * (1 + 0.8 * Math.max(0, p2) + 0.4 * aparecer(frame, tCost, 6) * (1 - aparecer(frame, tCost + 14, 10)));

  // Aire: velocidad de las rayas y turbulencia en la zona de costuras
  const fase = frame * 0.011 + 0.009 * Math.max(0, frame - tProb);
  const turb = 0.6 * aparecer(frame, tCamb, 16) + 0.4 * aparecer(frame, tAire, 10);
  const colorTurb = frame >= tCamb ? azul : celeste;

  const lineas = [0.3, 0.55, 0.76, -0.3, -0.55, -0.76];
  const ruta = (o: number, x: number, i: number): [number, number, number] => {
    const empuje = Math.max(0, R + 0.1 - Math.abs(o)) * Math.exp((-x * x) / 0.2) + 0.04 * Math.exp((-x * x) / 0.4);
    let y = o + Math.sign(o) * empuje;
    if (o < 0) {
      const e = Math.min(1, Math.max(0, (x + 0.1) / 0.35));
      y += turb * e * 0.075 * Math.sin(x * 13 - frame * 0.35 + i * 1.7);
    }
    return [x, CY + y, 0];
  };

  const aire: React.ReactNode[] = [];
  lineas.forEach((o, i) => {
    const col = o < 0 ? colorTurb : celeste;
    // trazo tenue de fondo
    for (let s = 0; s < 14; s++) {
      const xa = -0.97 + (s / 14) * 1.94;
      const xb = -0.97 + ((s + 1) / 14) * 1.94;
      aire.push(<Linea key={`b${i}-${s}`} desde={ruta(o, xa, i)} hasta={ruta(o, xb, i)} grosor={0.005} color={celesteTenue} />);
    }
    // rayas que corren con el viento
    for (let k = 0; k < 6; k++) {
      const s = (((k / 6 + fase + i * 0.13) % 1) + 1) % 1;
      const x0 = -0.97 + s * 1.94;
      const x1 = Math.min(0.97, x0 + 0.2);
      for (let j = 0; j < 3; j++) {
        const xa = x0 + ((x1 - x0) * j) / 3;
        const xb = x0 + ((x1 - x0) * (j + 1)) / 3;
        if (xb - xa < 0.005) continue;
        aire.push(<Linea key={`d${i}-${k}-${j}`} desde={ruta(o, xa, i)} hasta={ruta(o, xb, i)} grosor={0.012} color={col} />);
      }
    }
  });

  // Remolinos detrás de las costuras
  const remolinos = [
    {p: [0.42, 0.58, 0.12], r: 0.09},
    {p: [0.66, 0.5, 0.05], r: 0.11},
    {p: [0.9, 0.62, 0.0], r: 0.08},
    {p: [0.3, 0.74, 0.36], r: 0.06},
    {p: [0.78, 0.3, 0.05], r: 0.07},
  ];

  // Ojos: miran al aire cuando se habla de él
  const mirarX = mover(frame, [tAire - 4, tAire + 8], [0.1, 0.85]);
  const mirarY = mover(frame, [tAire - 4, tAire + 8], [0.3, -0.7]);

  // Ventilador del túnel al fondo
  const giroAspas = frame * (0.15 + 0.2 * aparecer(frame, tProb, 12));
  const aguja = mover(frame, [tProb, tProb + 14], [-0.9, 0.7]) + flotar(frame, 0.06, 20);

  return (
    <group>
      {/* ---------- Fondo: pared del túnel de viento con cuadrícula ---------- */}
      <Pieza forma="caja" medidas={[2.3, 1.95, 0.06]} color={pared} posicion={[0, 0.98, -0.95]} />
      {[-0.9, -0.6, -0.3, 0, 0.3, 0.6, 0.9].map((x) => (
        <Bloque key={`gv${x}`} tam={[0.012, 1.9, 0.01]} posicion={[x, 0.98, -0.915]} color={rejilla} />
      ))}
      {[0.3, 0.6, 0.9, 1.2, 1.5, 1.8].map((y) => (
        <Bloque key={`gh${y}`} tam={[2.26, 0.012, 0.01]} posicion={[0, y, -0.915]} color={rejilla} />
      ))}
      {/* ventilador al fondo */}
      <group position={[0.68, 1.5, -0.86]}>
        <Pieza forma="toro" medidas={[0.24, 0.035]} color={metalOscuro} />
        <Pieza forma="cilindro" medidas={[0.05, 0.05, 0.06]} color={metal} rotacion={[Math.PI / 2, 0, 0]} />
        <group rotation={[0, 0, giroAspas]}>
          {[0, 1, 2, 3].map((a) => (
            <Pieza key={a} forma="caja" medidas={[0.07, 0.19, 0.012]} color={crema} rotacion={[0.3, 0, (a * Math.PI) / 2]} posicion={[Math.sin((a * Math.PI) / 2) * -0.12, Math.cos((a * Math.PI) / 2) * 0.12, 0.02]} />
          ))}
        </group>
      </group>
      {/* suelo del túnel */}
      <Pieza forma="caja" medidas={[2.2, 0.05, 1.5]} color="#8E8A84" posicion={[0, 0.025, -0.15]} />
      {/* rejilla de entrada (izquierda) y salida (derecha) */}
      <Pieza forma="caja" medidas={[0.07, 1.8, 0.9]} color={metalOscuro} posicion={[-1.04, 0.95, -0.35]} />
      {[0.25, 0.55, 0.85, 1.15, 1.45, 1.75].map((y) => (
        <Pieza key={`s${y}`} forma="caja" medidas={[0.1, 0.025, 0.92]} color={metal} posicion={[-1.0, y, -0.35]} />
      ))}
      <Pieza forma="caja" medidas={[0.07, 1.8, 0.9]} color={metalOscuro} posicion={[1.04, 0.95, -0.35]} />

      {/* ---------- Medio: soporte con pinza y la pelota ---------- */}
      <Pieza forma="cilindro" medidas={[0.16, 0.18, 0.04]} color={metalOscuro} posicion={[0, 0.07, 0]} />
      <Pieza forma="cilindro" medidas={[0.025, 0.03, 0.42]} color={metal} posicion={[0, 0.3, 0]} />
      <Pieza forma="caja" medidas={[0.04, 0.1, 0.06]} color={metal} posicion={[-0.05, 0.52, 0]} rotacion={[0, 0, 0.35]} />
      <Pieza forma="caja" medidas={[0.04, 0.1, 0.06]} color={metal} posicion={[0.05, 0.52, 0]} rotacion={[0, 0, -0.35]} />

      <group position={[0, CY, 0]} rotation={[0, flotar(frame, 0.04, 90) + sacudida * Math.sin(frame * 0.9), 0]} scale={[1 + aplasta, 1 - aplasta, 1 + aplasta]}>
        <group rotation={[0.7, 0, 0]}>
          <group rotation={[0, 0, Math.PI / 4]}>
            <Pieza forma="esfera" medidas={[R]} color={cuero} />
            <mesh geometry={tuboCostura}>
              <meshBasicMaterial color="#B8AE9F" />
            </mesh>
            {puntadas.map(([a, b], i) => (
              <Linea key={i} desde={a} hasta={b} grosor={grosorPuntada} color={rojo} />
            ))}
          </group>
        </group>
        <Ojos posicion={[0, 0.17, 0.47]} tam={0.055} separacion={0.17} mirar={[mirarX, mirarY]} frame={frame} />
      </group>

      {/* ---------- El aire ---------- */}
      {aire}
      {remolinos.map((v, i) => {
        const e = aparecer(frame, tAire + i * 3, 8);
        return (
          <Pieza
            key={`r${i}`}
            forma="toro"
            medidas={[v.r, 0.013, 4.6]}
            color={azul}
            posicion={[v.p[0], v.p[1], v.p[2]]}
            rotacion={[0, 0, -frame * 0.28 - i * 1.3]}
            escala={e * (1 + 0.08 * Math.sin(frame * 0.3 + i))}
          />
        );
      })}

      {/* ---------- Etiquetas (máximo dos a la vez) ---------- */}
      <Etiqueta
        texto="costuras"
        punto={[0, CY - 0.14, 0.5]}
        desplazamiento={[-0.62, -0.32, 0.2]}
        escala={aparecer(frame, tCost + 2, 8) * (1 - aparecer(frame, tAire, 6))}
      />
      <Etiqueta texto="el aire" punto={[0.66, 0.5, 0.05]} desplazamiento={[0.12, -0.3, 0.35]} escala={aparecer(frame, tAire + 2, 8)} />
      <Etiqueta texto="zona lisa" punto={[-0.15, CY + 0.45, 0.2]} desplazamiento={[-0.5, 0.25, 0.3]} escala={aparecer(frame, tSup, 8)} />

      {/* ---------- Delante: pelota lisa y medidor del túnel ---------- */}
      <Pieza forma="cilindro" medidas={[0.17, 0.19, 0.03]} color={crema} posicion={[-0.7, 0.015, 0.72]} />
      <Pieza forma="esfera" medidas={[0.11]} color={cuero} posicion={[-0.7, 0.14, 0.72]} />
      <group position={[0.72, 0, 0.72]} rotation={[0, -0.35, 0]}>
        <Pieza forma="caja" medidas={[0.26, 0.18, 0.1]} color={metalOscuro} posicion={[0, 0.09, 0]} />
        <Pieza forma="cilindro" medidas={[0.07, 0.07, 0.02]} color={crema} posicion={[0, 0.1, 0.055]} rotacion={[Math.PI / 2, 0, 0]} />
        <Pieza forma="caja" medidas={[0.008, 0.055, 0.008]} color={mostaza} posicion={[0, 0.1, 0.07]} rotacion={[0, 0, -aguja]} contorno={false} />
        <Pieza forma="cilindro" medidas={[0.012, 0.012, 0.03]} color={metal} posicion={[0.1, 0.1, 0.055]} rotacion={[Math.PI / 2, 0, 0]} />
      </group>
    </group>
  );
};

escenas.Escena1:
import React from 'react';
import {interpolate} from 'remotion';
import * as THREE from 'three';
import {EscenaProps, Pieza, Etiqueta, Brillo, Linea, Mat, aparecer, mover, momento, V3} from '../lib3d';

// Escena 2: «Cada pelota oficial lleva ciento ocho puntadas dobles cosidas a mano...»
// Una mano cose con hilo rojo la pelota gigante: la pelota gira bajo la aguja y cada puntada
// nueva salta con una chispa. Al final entran unas pinzas a quitar una puntada.

const R = 0.6;
const N = 108;
const CX = -0.1;
const CY = 1.0;
const ROJO = '#B4473A';
const PIEL = '#EAC4A2';
const METAL = '#A3A7AB';
const CUERO = '#F2EEE6';

// Curva real de la costura (curva doble sobre la esfera).
const curva = (t: number) => {
  const a = 0.7;
  const b = 0.3;
  const c = 2 * Math.sqrt(a * b);
  const v = new THREE.Vector3(a * Math.cos(t) + b * Math.cos(3 * t), c * Math.sin(2 * t), a * Math.sin(t) - b * Math.sin(3 * t));
  return v.normalize().multiplyScalar(R);
};

type Puntada = {p: V3; n: V3; q: THREE.Quaternion; t: number};
type Datos = {st: Puntada[]; tubo: THREE.TubeGeometry; caja: THREE.BoxGeometry};
let cache: Datos | null = null;

const datos = (): Datos => {
  if (cache) return cache;
  const M = 900;
  const largos: number[] = [0];
  let prev = curva(0);
  for (let i = 1; i <= M; i++) {
    const v = curva((i / M) * Math.PI * 2);
    largos.push(largos[i - 1] + v.distanceTo(prev));
    prev = v;
  }
  const total = largos[M];
  const st: Puntada[] = [];
  let j = 0;
  for (let i = 0; i < N; i++) {
    const meta = ((i + 0.5) / N) * total;
    while (j < M - 1 && largos[j + 1] < meta) j++;
    const t = ((j + (meta - largos[j]) / (largos[j + 1] - largos[j])) / M) * Math.PI * 2;
    const pos = curva(t);
    const nn = pos.clone().normalize();
    const tan = curva(t + 0.001).sub(curva(t - 0.001)).normalize();
    const bin = new THREE.Vector3().crossVectors(nn, tan).normalize();
    const tan2 = new THREE.Vector3().crossVectors(bin, nn);
    const q = new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(tan2, bin, nn));
    const p = pos.multiplyScalar(1.004);
    st.push({p: [p.x, p.y, p.z], n: [nn.x, nn.y, nn.z], q, t});
  }
  const puntos = Array.from({length: 240}, (_, i) => curva((i / 240) * Math.PI * 2).multiplyScalar(1.001));
  const tubo = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(puntos, true), 480, 0.005, 6, true);
  const caja = new THREE.BoxGeometry(0.011, 0.045, 0.01);
  cache = {st, tubo, caja};
  return cache;
};

const suma = (a: V3, b: V3, k = 1): V3 => [a[0] + b[0] * k, a[1] + b[1] * k, a[2] + b[2] * k];
const salto = (fr: number, t0: number) => (fr >= t0 && fr <= t0 + 12 ? Math.sin(((fr - t0) / 12) * Math.PI) : 0);

export const Escena1: React.FC<EscenaProps> = ({frame, fps, palabras, paleta}) => {
  const [, secundario, resalte, extra] = paleta.acentos;
  const {st, tubo, caja} = datos();

  const tPunt = momento(palabras, fps, 'puntadas', 46);
  const tMano = Math.max(10, momento(palabras, fps, 'mano', 76));
  const tRaro = momento(palabras, fps, 'raro', 106);
  const tPasa = momento(palabras, fps, 'pasa', 136);
  const tQuitas = momento(palabras, fps, 'quitas', 166);

  // Avance del cosido: desde el fotograma 0 ya hay media pelota cosida; termina en "mano".
  const estado = (fr: number) => {
    const s = interpolate(fr, [0, tMano], [0.55, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
    const k = s * N;
    const kk = Math.min(k, N - 0.001);
    const i = Math.floor(kk);
    const j = Math.min(i + 1, N - 1);
    const tA = st[i].t + (st[j].t - st[i].t) * (kk - i);
    return {k, i, rot: tA - 0.8 + Math.max(0, fr - tMano) * 0.006};
  };
  const {k, i: iAct, rot} = estado(frame);
  const cy = CY + 0.07 * salto(frame, tRaro) + 0.04 * salto(frame, tMano);
  const c = Math.cos(rot);
  const sn = Math.sin(rot);
  const mundo = (p: V3): V3 => [CX + p[0] * c + p[2] * sn, p[1] + cy, -p[0] * sn + p[2] * c];
  const dirMundo = (n: V3): V3 => [n[0] * c + n[2] * sn, n[1], -n[0] * sn + n[2] * c];

  // Mano con aguja siguiendo la puntada activa.
  const act = st[iAct];
  const sup = mundo(act.p);
  const nW = dirMundo(act.n);
  const dl = Math.hypot(nW[0], nW[1] * 0.4, nW[2]);
  const d: V3 = [nW[0] / dl, (nW[1] * 0.4) / dl, nW[2] / dl];
  const cosiendo = frame < tMano;
  const bob = cosiendo ? Math.sin(((k / 3) % 1) * Math.PI) : 0;
  const tira = mover(frame, [tMano, tMano + 12], [0, 0.08]);
  const sale = mover(frame, [tPasa - 8, tPasa + 8], [0, 1.2]);
  const tip = suma(sup, d, 0.05 - 0.07 * bob + tira + sale);
  const H = suma(tip, d, 0.3);
  const ojoAguja = suma(tip, d, 0.21);
  const th = Math.atan2(-d[2], d[0]);
  const el = Math.asin(Math.max(-1, Math.min(1, d[1])));
  const ultima = mundo(st[Math.max(0, Math.ceil(k) - 1)].p);

  // Puntada que quitarán las pinzas (la más visible arriba a la izquierda al final).
  const rq = estado(tQuitas).rot;
  const cq = Math.cos(rq);
  const sq = Math.sin(rq);
  let kP = 0;
  let mejor = -99;
  st.forEach((p, idx) => {
    const xw = p.p[0] * cq + p.p[2] * sq;
    const zw = -p.p[0] * sq + p.p[2] * cq;
    const score = -xw + zw * 1.3 + p.p[1] * 0.6;
    if (zw > 0 && score > mejor) {
      mejor = score;
      kP = idx;
    }
  });
  const lift = mover(frame, [tQuitas, tQuitas + 6], [0, 0.1]);
  const pinzaTip = mundo(suma(st[kP].p, st[kP].n, 0.015 + lift));
  const entraPinza = 1 - aparecer(frame, tPasa, 12);
  const gap = mover(frame, [tQuitas - 4, tQuitas + 2], [0.1, 0.02]);
  const angPinza = Math.atan((gap / 2 - 0.012) / 0.56);

  // Chispas de cada puntada nueva.
  const fr = k % 1;
  const chispa = suma(mundo(act.p), nW, 0.03);
  const flash = frame >= tMano && frame < tMano + 10 ? 1 - (frame - tMano) / 10 : 0;

  const e1 = aparecer(frame, tPunt, 8) * (1 - aparecer(frame, tPasa - 6, 6));
  const e2 = aparecer(frame, tMano, 8) * (1 - aparecer(frame, tPasa - 10, 6));

  return (
    <group>
      {/* Fondo: caja de pelotas y bate */}
      <group position={[-0.95, 0, -0.95]} rotation={[0, 0.35, 0]}>
        <Pieza forma="caja" medidas={[0.6, 0.32, 0.42]} color="#A8845A" posicion={[0, 0.16, 0]} />
        <Pieza forma="caja" medidas={[0.62, 0.05, 0.44]} color="#8C6A44" posicion={[0, 0.07, 0]} />
        <Pieza forma="caja" medidas={[0.62, 0.05, 0.44]} color="#8C6A44" posicion={[0, 0.27, 0]} />
        {[-0.14, 0.14].map((x, i) => (
          <group key={i} position={[x, 0.43, i * 0.03]}>
            <Pieza forma="esfera" medidas={[0.12]} color={CUERO} />
            <Pieza forma="toro" medidas={[0.12, 0.006]} color={ROJO} rotacion={[0.6, 0.3 + i, 0]} contorno={false} />
          </group>
        ))}
      </group>
      <group position={[0.95, 0.045, -1.05]} rotation={[0, -0.6, 0]}>
        <Pieza forma="cilindro" medidas={[0.045, 0.018, 0.9]} color="#B58A5A" rotacion={[0, 0, Math.PI / 2]} />
        <Pieza forma="cilindro" medidas={[0.03, 0.03, 0.02]} color="#8C6A44" posicion={[0.46, 0, 0]} rotacion={[0, 0, Math.PI / 2]} />
      </group>

      {/* Soporte de laboratorio */}
      <Pieza forma="cilindro" medidas={[0.3, 0.34, 0.06]} color="#7E7A75" posicion={[CX, 0.03, 0]} />
      <Pieza forma="cilindro" medidas={[0.045, 0.045, 0.36]} color={METAL} posicion={[CX, 0.24, 0]} />
      <Pieza forma="toro" medidas={[0.2, 0.025]} color={METAL} posicion={[CX, 0.44, 0]} rotacion={[Math.PI / 2, 0, 0]} />

      {/* La pelota gigante con su costura y las puntadas en V */}
      <group position={[CX, cy, 0]} rotation={[0, rot, 0]}>
        <Pieza forma="esfera" medidas={[R]} color={CUERO} />
        <mesh geometry={tubo}>
          <Mat color="#9C948A" />
        </mesh>
        {st.map((p, idx) => {
          const e = Math.max(0, Math.min(1, (k - idx) * 2));
          if (e <= 0.001) return null;
          const pos = idx === kP ? suma(p.p, p.n, lift) : p.p;
          return (
            <group key={idx} position={pos} quaternion={p.q} scale={e}>
              {[-1, 1].map((l) => (
                <mesh key={l} geometry={caja} position={[0.008, l * 0.02, 0]} rotation={[0, 0, l * 0.55]} castShadow>
                  <Mat color={ROJO} />
                </mesh>
              ))}
            </group>
          );
        })}
      </group>

      {/* Chispas de cada puntada */}
      {frame < tMano + 3 ? (
        <group>
          <Brillo posicion={chispa} color={extra} radio={0.012 + 0.025 * (1 - fr)} />
          {[0, 1, 2].map((j) => {
            const a = j * 2.09 + iAct * 0.7;
            return <Brillo key={j} posicion={[chispa[0] + Math.cos(a) * 0.09 * fr, chispa[1] + Math.sin(a) * 0.09 * fr, chispa[2] + 0.02]} color={extra} radio={0.009 * (1 - fr) + 0.003} />;
          })}
        </group>
      ) : null}
      {flash > 0 ? <Brillo posicion={suma(ultima, nW, 0.04)} color={extra} radio={0.07 * flash} /> : null}

      {/* Hilo y aguja */}
      {frame < tPasa + 8 ? <Linea desde={ojoAguja} hasta={ultima} grosor={0.004} color={ROJO} /> : null}
      <Linea desde={tip} hasta={suma(tip, d, 0.22)} grosor={0.006} color={METAL} />

      {/* Mano del costurero con puño azul */}
      <group position={H} rotation={[0, th, el]}>
        <Pieza forma="esfera" medidas={[0.1]} color={PIEL} escala={[1, 0.82, 0.6]} />
        <Pieza forma="capsula" medidas={[0.026, 0.08]} color={PIEL} posicion={[-0.12, 0.03, 0.01]} rotacion={[0, 0, Math.PI / 2]} />
        <Pieza forma="capsula" medidas={[0.028, 0.06]} color={PIEL} posicion={[-0.11, -0.035, 0.035]} rotacion={[0, 0.3, Math.PI / 2 + 0.4]} />
        {[0, 1, 2].map((j) => (
          <Pieza key={j} forma="esfera" medidas={[0.03]} color={PIEL} posicion={[-0.07, 0.01 - j * 0.03, -0.045]} />
        ))}
        <Pieza forma="cilindro" medidas={[0.085, 0.085, 0.07]} color="#3E5F8A" posicion={[0.1, 0, 0]} rotacion={[0, 0, Math.PI / 2]} />
        <Pieza forma="cilindro" medidas={[0.09, 0.1, 0.7]} color={secundario} posicion={[0.48, 0, 0]} rotacion={[0, 0, Math.PI / 2]} />
      </group>

      {/* Pinzas que llegan a quitar una puntada */}
      {frame >= tPasa ? (
        <group position={[pinzaTip[0] - 0.8 * entraPinza, pinzaTip[1] + 0.8 * entraPinza, pinzaTip[2]]} rotation={[0, 0, 0.75]}>
          {[-1, 1].map((l) => (
            <Pieza key={l} forma="caja" medidas={[0.03, 0.56, 0.018]} color={METAL} posicion={[(l * (gap / 2 + 0.012)) / 2, 0.28, 0]} rotacion={[0, 0, l * angPinza]} />
          ))}
          <Pieza forma="cilindro" medidas={[0.03, 0.03, 0.05]} color="#7E7A75" posicion={[0, 0.56, 0]} rotacion={[Math.PI / 2, 0, 0]} />
        </group>
      ) : null}

      {/* Etiquetas */}
      <Etiqueta texto="108 puntadas" punto={[-0.55, 1.25, 0.32]} desplazamiento={[-0.05, 0.53, 0]} alto={0.15} escala={e1} />
      <Etiqueta texto="cosidas a mano" punto={H} desplazamiento={[0.45 - H[0], 1.8 - H[1], 0.3 - H[2]]} alto={0.15} color={resalte} escala={e2} />

      {/* Delante: carrete de hilo rojo */}
      <group position={[-0.62, 0, 0.75]}>
        <Pieza forma="cilindro" medidas={[0.085, 0.085, 0.022]} color="#C9A47A" posicion={[0, 0.011, 0]} />
        <Pieza forma="cilindro" medidas={[0.065, 0.065, 0.136]} color={ROJO} posicion={[0, 0.09, 0]} />
        <Pieza forma="cilindro" medidas={[0.085, 0.085, 0.022]} color="#C9A47A" posicion={[0, 0.169, 0]} />
        <Linea desde={[0.06, 0.1, 0.03]} hasta={[0.3, 0.004, 0.12]} grosor={0.003} color={ROJO} />
      </group>
    </group>
  );
};
